select count(*) as total_events,
  count(distinct sport_name) as sports,
  count(*) filter (where status = 'Pending') as pending_events,
  count(*) filter (where coordinatorid is not null or goldteamid is not null
    or silverteamid is not null or bronzeteamid is not null
    or gold_winner_name is not null or silver_winner_name is not null
    or bronze_winner_name is not null) as rows_with_old_results
from public.prov_events;

